import React, {
    useRef,
    useEffect,
    useLayoutEffect,
    useState,
    useMemo,
    useCallback,
} from "react"
// Standalone Framer Shim for Next.js / React
const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};


// Read the CMS slot BEFORE the browser paints (client only), so a connected
// collection doesn't flash the placeholder sections first. Falls back to a
// plain effect on the server (no useLayoutEffect warning).
const useIsoLayoutEffect =
    typeof window !== "undefined" ? useLayoutEffect : useEffect

// ---- types -------------------------------------------------------------

type ImgValue = { src?: string } | string | undefined

interface ManualItem {
    image?: ImgValue
    primary?: string
    primaryColor?: string
    script?: string
    scriptColor?: string
    link?: string
}

interface Resolved {
    src: string
    primary: string
    primaryColor: string
    script: string
    scriptColor: string
    href: string
}

interface MarqueeState {
    panel: number
    kind: "primary" | "script"
    svg: any
    tp: any
    path: any
    g: any
    text: any
    textEl: HTMLElement
    wrap: HTMLElement
    loopLen: number
    speedPx: number
    offsetX: number
}

interface Props {
    source?: "manual" | "cms"
    items?: ManualItem[]
    collectionSlot?: React.ReactNode
    words?: {
        count?: "one" | "two"
        color1?: string
        color2?: string
    }
    typography?: {
        custom?: boolean
        font1?: React.CSSProperties
        size1?: number
        font2?: React.CSSProperties
        size2?: number
    }
    marquee?: {
        radius?: number
        primarySpeed?: number
        scriptSpeed?: number
    }
    effects?: {
        textRise?: number
        blend?: "normal" | "difference" | "exclusion" | "overlay" | "outline"
        motionBlur?: number
        zoom?: boolean
        depth?: boolean
    }
    motion?: {
        sectionHeight?: number
        wheel?: boolean
        parallax?: number
        snapDuration?: number
        newTab?: boolean
    }
    style?: {
        background?: string
    }
    width?: number
    height?: number
}

// ---- constants ---------------------------------------------------------

const RED = "#EE2625"
const WHITE = "#FFFFFF"
const NS = "http://www.w3.org/2000/svg"
const XNS = "http://www.w3.org/1999/xlink"
// Fonts are BUNDLED into the component as base64 @font-face, so there is NO
// runtime request to a third-party CDN (Google Fonts). League Gothic is the
// wdth-80 instance; Ms Madi is the cursive.
const LEAGUE_B64 = ""
const MSMADI_B64 = ""
const FONT_FACE_CSS =
    "@font-face{font-family:'League Gothic';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64," +
    LEAGUE_B64 +
    ") format('woff2')}" +
    "@font-face{font-family:'Ms Madi';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64," +
    MSMADI_B64 +
    ") format('woff2')}"

// Applied to the document via a constructable stylesheet (adoptedStyleSheets),
// NOT dangerouslySetInnerHTML, so React's escaping is never bypassed. Because
// FONT_FACE_CSS above is a static module constant (base64 data-URIs only), no
// dynamic or user-provided value can ever enter the injected CSS. One shared
// sheet is reused across every instance. A legacy <style> fallback (textContent,
// not innerHTML) covers the rare browser without constructable-stylesheet support.
let fontSheet: CSSStyleSheet | null = null
function ensureFontFaces(): void {
    if (typeof document === "undefined") return
    const supportsConstructable =
        "adoptedStyleSheets" in document &&
        typeof CSSStyleSheet === "function" &&
        "replaceSync" in CSSStyleSheet.prototype
    if (supportsConstructable) {
        try {
            if (!fontSheet) {
                fontSheet = new CSSStyleSheet()
                fontSheet.replaceSync(FONT_FACE_CSS)
            }
            if (!document.adoptedStyleSheets.includes(fontSheet)) {
                document.adoptedStyleSheets = [
                    ...document.adoptedStyleSheets,
                    fontSheet,
                ]
            }
            return
        } catch {
            // fall through to the element fallback below
        }
    }
    if (document.getElementById("infinite-story-fonts")) return
    const el = document.createElement("style")
    el.id = "infinite-story-fonts"
    el.textContent = FONT_FACE_CSS
    document.head.appendChild(el)
}

const PRIMARY_FONT = "'League Gothic', sans-serif"
const SCRIPT_FONT = "'Ms Madi', cursive"
// the demo's clamp()s, in px (its root is 62.5% so 12rem=120px, 32rem=320px, etc.)
const PRIMARY_SIZE = "clamp(120px, 20vw, 320px)"
const SCRIPT_SIZE = "clamp(80px, 12vw, 240px)"

const PLACEHOLDERS: Resolved[] = [
    {
        src: "https://framerusercontent.com/images/MbQDCV4nGN49RCxX1eBLnjMZw.jpg",
        primary: "Founder",
        primaryColor: WHITE,
        script: "Creator",
        scriptColor: RED,
        href: "",
    },
    {
        src: "https://framerusercontent.com/images/3YdJNmzQEerhKI0YD9X3Yq57XKo.jpg",
        primary: "Producer",
        primaryColor: RED,
        script: "Executive",
        scriptColor: WHITE,
        href: "",
    },
    {
        src: "https://framerusercontent.com/images/U9KognNNwrdTSK4tnpe1gvjuDKs.jpg",
        primary: "Psychic",
        primaryColor: RED,
        script: "Celebrity",
        scriptColor: WHITE,
        href: "",
    },
]

// ---- helpers (ported from the OSMO radial marquee) ---------------------

function srcOf(value: ImgValue): string {
    if (!value) return ""
    return typeof value === "string" ? value : value.src ?? ""
}

function resolveManual(items?: ManualItem[]): Resolved[] {
    if (!items || items.length === 0) return PLACEHOLDERS
    const out: Resolved[] = []
    for (const it of items) {
        const src = srcOf(it.image)
        if (!src && !it.primary && !it.script) continue
        out.push({
            src,
            primary: it.primary ?? "",
            primaryColor: it.primaryColor ?? WHITE,
            script: it.script ?? "",
            scriptColor: it.scriptColor ?? RED,
            href: it.link ?? "",
        })
    }
    return out.length ? out : PLACEHOLDERS
}

function clampN(n: number | string, a: number, b: number) {
    return Math.min(b, Math.max(a, Number(n) || 0))
}

function easeOutQuart(t: number) {
    return 1 - Math.pow(1 - t, 4)
}

// width-aware speed multiplier, matching the demo
function speedMul() {
    const w = (typeof window !== "undefined" && window.innerWidth) || 2000
    const t = clampN((w - 250) / (2000 - 250), 0, 1)
    return 0.5 + t * 0.5
}

// arc radius from a 0..1 "roundness" level
function circleR(half: number, level01: number) {
    if (level01 <= 0) return half * 200
    const inv = 1 - level01
    return half * (1.01 + inv * inv * 16.99)
}

let _ctx: CanvasRenderingContext2D | null = null
function measureText(str: string, fontCss: string) {
    if (typeof document === "undefined") return 0
    if (!_ctx) _ctx = document.createElement("canvas").getContext("2d")
    if (!_ctx) return 0
    _ctx.font = fontCss
    return _ctx.measureText(str || "").width || 0
}

// ---- component ---------------------------------------------------------

/**
 * @framerIntrinsicWidth 1200
 * @framerIntrinsicHeight 700
 *
 * @framerDisableUnlink
 *
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 */
export default function InfiniteStory(props: Props) {
    const {
        source = "manual",
        items,
        collectionSlot,
        words = {},
        typography = {},
        marquee = {},
        effects = {},
        motion = {},
        style = {},
    } = props

    const wordCount = words.count ?? "two"
    const cmsColor1 = words.color1 ?? WHITE
    const cmsColor2 = words.color2 ?? RED

    // Type: off keeps the signature League Gothic + Ms Madi; on lets the user
    // set their own font + size (in vw) per word. The marquee reads whatever is
    // set on the hidden heading via getComputedStyle, so overriding it here is
    // all that's needed.
    const customType = typography.custom ?? false
    const font1 = typography.font1
    const size1 = clampN(typography.size1 ?? 20, 3, 40)
    const font2 = typography.font2
    const size2 = clampN(typography.size2 ?? 12, 3, 40)

    const radius = marquee.radius ?? 8
    const primarySpeed = marquee.primarySpeed ?? 2
    const scriptSpeed = marquee.scriptSpeed ?? 4

    const textRise = clampN(effects.textRise ?? 20, 0, 100)
    const blend = effects.blend ?? "normal"
    const motionBlur = clampN(effects.motionBlur ?? 6, 0, 20)
    const zoom = effects.zoom ?? true
    const depth = effects.depth ?? true

    const sectionHeight = motion.sectionHeight ?? 100
    const wheel = motion.wheel ?? true
    const parallax = motion.parallax ?? 50
    // snap glide, in ms (the control is in seconds)
    const snapMs = Math.max(100, (motion.snapDuration ?? 0.9) * 1000)
    const newTab = motion.newTab ?? false

    const background = style.background ?? "#000000"

    const isStatic = useIsStaticRenderer()

    // resolved sections (manual, or CMS via the hidden probe)
    const manualItems = useMemo(() => resolveManual(items), [items])
    const [cmsItems, setCmsItems] = useState<Resolved[]>([])
    // In CMS mode: show the real rows once read. Before that, only fall back to
    // PLACEHOLDERS in the CANVAS/export (isStatic) so the design previews
    // something — on the LIVE site show nothing (just the background) rather
    // than flashing the placeholder story before the CMS rows resolve.
    const resolved =
        source === "cms"
            ? cmsItems.length
                ? cmsItems
                : isStatic
                  ? PLACEHOLDERS
                  : []
            : manualItems
    const N = resolved.length

    // refs
    const rootRef = useRef<HTMLDivElement | null>(null)
    const probeRef = useRef<HTMLDivElement | null>(null)
    const panelRefs = useRef<(HTMLDivElement | null)[]>([])
    const mediaRefs = useRef<(HTMLDivElement | null)[]>([])
    const imgRefs = useRef<(HTMLImageElement | null)[]>([])
    const textRefs = useRef<(HTMLDivElement | null)[]>([])
    const marqueeStatesRef = useRef<MarqueeState[]>([])
    // src -> the real anchor inside the CMS slot, for Framer-routed clicks
    const anchorsRef = useRef<Map<string, HTMLAnchorElement>>(new Map())
    const resolvedRef = useRef<Resolved[]>(resolved)
    resolvedRef.current = resolved
    const centerIdxRef = useRef(0)
    const movedRef = useRef(false)
    const newTabRef = useRef(newTab)
    newTabRef.current = newTab

    const offRef = useRef(0)
    const prevOffRef = useRef(0)
    const rawRef = useRef(0)
    const velRef = useRef(0)
    const modeRef = useRef<"idle" | "scrub" | "snap">("idle")
    const snapStartRef = useRef(0)
    const snapTargetRef = useRef(0)
    const snapT0Ref = useRef(0)
    const lastInputRef = useRef(0)
    const lastFrameRef = useRef(0)

    const draggingRef = useRef(false)
    const startYRef = useRef(0)
    const startRawRef = useRef(0)

    // Apply the bundled @font-face via adoptedStyleSheets (replaces the former
    // dangerouslySetInnerHTML <style>). Runs on the live site and the canvas
    // design view; effects do not run during static export/thumbnail, matching
    // the dedicated static-path rule. No cleanup: the single shared sheet holds
    // only inert @font-face rules (data-URIs, loaded lazily), and removing it on
    // one instance's unmount would break any other instance still mounted.
    useIsoLayoutEffect(() => {
        ensureFontFaces()
    }, [])

    // ---- CMS slot probe -------------------------------------------------
    // reads one img + up to two text strings per row: first text -> Word 1,
    // second text -> Word 2 (bind Title / Subtitle CMS fields to those layers).
    // runs on the canvas too (isStatic) so the design view previews real CMS.
    // LAYOUT effect: the first read runs before paint, so a slot that's already
    // in the DOM resolves without any placeholder flash.
    useIsoLayoutEffect(() => {
        // Dedicated static path: NO DOM observation on the canvas / during
        // export. Static falls back to the placeholder sections (see `resolved`).
        if (RenderTarget.current() === RenderTarget.export || RenderTarget.current() === RenderTarget.thumbnail || source !== "cms") return
        const probe = probeRef.current
        if (!probe) return
        const read = () => {
            const out: Resolved[] = []
            const seen = new Set<string>()
            anchorsRef.current.clear()
            probe.querySelectorAll("img").forEach((img) => {
                const src =
                    (img as HTMLImageElement).currentSrc ||
                    img.getAttribute("src") ||
                    ""
                if (!src) return
                // nearest ancestor row that actually holds text (img has none)
                let row: HTMLElement | null = img.parentElement
                while (
                    row &&
                    row !== probe &&
                    !(row.textContent || "").trim()
                ) {
                    row = row.parentElement
                }
                // gather leaf text layers in DOM order
                const texts: string[] = []
                if (row) {
                    row.querySelectorAll("*").forEach((el) => {
                        if (el.children.length !== 0) return
                        const t = (el.textContent || "").trim()
                        if (t && !texts.includes(t)) texts.push(t)
                    })
                }
                const primary = texts[0] || img.getAttribute("alt") || ""
                const script = texts[1] || ""
                // the real anchor (if the row/image is linked) for click routing
                let href = ""
                const a = img.closest("a") as HTMLAnchorElement | null
                if (a) {
                    href = a.getAttribute("href") || ""
                    anchorsRef.current.set(src, a)
                }
                const key = src + "|" + primary
                if (seen.has(key)) return
                seen.add(key)
                out.push({
                    src,
                    primary,
                    primaryColor: cmsColor1,
                    script,
                    scriptColor: cmsColor2,
                    href,
                })
            })
            setCmsItems((prev) => {
                if (
                    prev.length === out.length &&
                    prev.every(
                        (p, i) =>
                            p.src === out[i].src &&
                            p.primary === out[i].primary &&
                            p.script === out[i].script
                    )
                )
                    return prev
                return out
            })
        }
        read()
        // Debounce: coalesce bursts of mutations into ONE read per frame instead
        // of a full rescan on every mutation (cheaper in the CMS editor).
        let scheduled = 0
        const schedule = () => {
            if (scheduled) return
            scheduled = requestAnimationFrame(() => {
                scheduled = 0
                read()
            })
        }
        const obs = new MutationObserver(schedule)
        obs.observe(probe, {
            childList: true,
            subtree: true,
            attributes: true,
            characterData: true,
            attributeFilter: ["src", "srcset", "currentSrc", "alt", "href"],
        })
        return () => {
            obs.disconnect()
            if (scheduled) cancelAnimationFrame(scheduled)
        }
    }, [isStatic, source, collectionSlot, cmsColor1, cmsColor2])

    // ---- build the curved marquees (imperative SVG, like the demo) ------
    useEffect(() => {
        if (isStatic) return
        const root = rootRef.current
        if (!root) return

        const buildOne = (wrap: HTMLElement): MarqueeState | null => {
            const textEl = wrap.querySelector("[data-rtm-text]") as HTMLElement | null
            if (!textEl) return null
            const baseText = (textEl.textContent || "").trim()
            if (!baseText) return null

            const panel = Number(wrap.getAttribute("data-panel") || 0)
            const kind = (wrap.getAttribute("data-kind") as "primary" | "script") || "primary"
            const speed = clampN(wrap.getAttribute("data-speed") || 4, 0.1, 200)
            const speedPx = Math.max(speed * 100 * speedMul(), 1)
            const level01 = clampN(wrap.getAttribute("data-radius") || 10, 0, 10) / 10
            const spacer = wrap.getAttribute("data-spacer") || "."
            const spacerColor = wrap.getAttribute("data-spacer-color") || null
            const isOutline = blend === "outline"
            const pad = " "

            // read the rendered (hidden) heading's type
            const cs = getComputedStyle(textEl)
            const fsPx = parseFloat(cs.fontSize) || 16
            const fontCss = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`
            const tt = cs.textTransform

            const cased = (v: string) => (tt === "uppercase" ? v.toUpperCase() : v)

            // build the svg skeleton
            const svg: any = document.createElementNS(NS, "svg")
            const defs: any = document.createElementNS(NS, "defs")
            const g: any = document.createElementNS(NS, "g")
            const path: any = document.createElementNS(NS, "path")
            const text: any = document.createElementNS(NS, "text")
            const tp: any = document.createElementNS(NS, "textPath")
            const id = `rtm-${Math.random().toString(16).slice(2)}`

            svg.setAttribute("xmlns", NS)
            svg.setAttribute("xmlns:xlink", XNS)
            Object.assign(svg.style, {
                position: "absolute",
                top: "0",
                left: "0",
                overflow: "visible",
                pointerEvents: "none",
                display: "block",
                transformOrigin: "50% 50%",
            })
            // reactive-text blend mode (difference / exclusion / overlay)
            if (!isOutline && blend !== "normal") svg.style.mixBlendMode = blend
            svg.setAttribute("aria-hidden", "true")
            path.setAttribute("id", id)
            path.setAttribute("fill", "none")
            path.setAttribute("stroke", "none")
            tp.setAttributeNS(XNS, "xlink:href", `#${id}`)
            tp.setAttribute("text-anchor", "start")
            tp.setAttribute("startOffset", "0px")
            text.appendChild(tp)
            defs.appendChild(path)
            svg.appendChild(defs)
            g.appendChild(path)
            g.appendChild(text)
            svg.appendChild(g)
            wrap.appendChild(svg)

            text.setAttribute("font-family", cs.fontFamily)
            text.setAttribute("font-size", cs.fontSize)
            text.setAttribute("font-weight", cs.fontWeight)
            text.setAttribute("font-style", cs.fontStyle)
            if (cs.letterSpacing && cs.letterSpacing !== "normal")
                text.setAttribute("letter-spacing", cs.letterSpacing)
            text.setAttribute("dominant-baseline", "alphabetic")
            if (isOutline) {
                // hollow stroked letters
                text.setAttribute("fill", "transparent")
                text.setAttribute("stroke", cs.color)
                text.setAttribute("stroke-width", String(Math.max(fsPx * 0.012, 1)))
                text.setAttribute("paint-order", "stroke")
            } else {
                text.setAttribute("fill", cs.color)
            }
            if (kind === "primary")
                text.style.fontVariationSettings = "'wdth' 80"

            // geometry
            const wrapW = Math.max(wrap.clientWidth || 1, 1)
            const wrapH = Math.max(wrap.clientHeight || textEl.offsetHeight || 1, 1)
            const bleed = fsPx * 2
            const w = wrapW + bleed * 2
            const h = wrapH
            Object.assign(svg.style, { width: `${w}px`, height: `${h}px`, left: `${-bleed}px` })
            svg.setAttribute("width", String(w))
            svg.setAttribute("height", String(h))
            svg.setAttribute("viewBox", `0 0 ${w} ${h}`)

            const half = w / 2
            const r = level01 <= 0.0001 ? half * 200 : Math.max(circleR(half, level01), half + 0.001)
            const under = Math.max(r * r - half * half, 0)
            const arcHeight = Math.max(r - Math.sqrt(under), 0)
            const baseline = h / 2 + fsPx * 0.35
            const y = Math.max(baseline - arcHeight / 2, 0)
            path.setAttribute(
                "d",
                level01 <= 0.0001 ? `M 0 ${y} L ${w} ${y}` : `M 0 ${y} A ${r} ${r} 0 0 0 ${w} ${y}`
            )
            text.setAttribute("x", "0")
            text.setAttribute("y", `${y}`)

            // repeat the run enough to cover the arc a few times over
            const loop0 =
                measureText(cased(baseText), fontCss) +
                measureText(pad, fontCss) +
                measureText(cased(spacer), fontCss) +
                measureText(pad, fontCss)
            const pathLen = path.getTotalLength ? path.getTotalLength() : wrapW
            const targetCover = Math.max(pathLen * 4, wrapW * 8)
            const reps = clampN(Math.ceil(targetCover / Math.max(loop0, 1)) + 6, 6, 600)

            const addTspan = (v: string, fill: string | null) => {
                const t: any = document.createElementNS(NS, "tspan")
                t.textContent = v
                // in outline mode the tspans inherit the text's transparent fill + stroke
                if (fill && !isOutline) t.setAttribute("fill", fill)
                tp.appendChild(t)
            }
            tp.textContent = ""
            for (let i = 0; i < reps; i++) {
                addTspan(cased(baseText), null)
                addTspan(pad, null)
                addTspan(cased(spacer), spacerColor)
                addTspan(pad, null)
            }

            // vertically center the run on the arc
            try {
                const bb = text.getBBox()
                const centerOffset = h / 2 - (bb.y + bb.height / 2)
                g.setAttribute("transform", `translate(0 ${centerOffset})`)
            } catch (e) {
                g.setAttribute("transform", "translate(0 0)")
            }

            let loopLen = Math.max(loop0, 1)
            try {
                const full = tp.getComputedTextLength()
                if (Number.isFinite(full) && full > 0) loopLen = full / reps
            } catch (e) {}

            return {
                panel,
                kind,
                svg,
                tp,
                path,
                g,
                text,
                textEl,
                wrap,
                loopLen: Math.max(loopLen, 1),
                speedPx,
                offsetX: 0,
            }
        }

        const buildAll = () => {
            // tear down previous svgs
            marqueeStatesRef.current.forEach((s) => {
                if (s.svg && s.svg.parentNode) s.svg.parentNode.removeChild(s.svg)
            })
            const wraps = root.querySelectorAll("[data-rtm-wrap]")
            const states: MarqueeState[] = []
            wraps.forEach((wrap) => {
                const s = buildOne(wrap as HTMLElement)
                if (s) states.push(s)
            })
            marqueeStatesRef.current = states
        }

        buildAll()

        // rebuild after fonts load and on resize (measurement depends on both)
        let raf = 0
        const schedule = () => {
            cancelAnimationFrame(raf)
            raf = requestAnimationFrame(buildAll)
        }
        if ((document as any).fonts && (document as any).fonts.ready) {
            ;(document as any).fonts.ready.then(schedule).catch(() => {})
        }
        const ro =
            typeof ResizeObserver !== "undefined" ? new ResizeObserver(schedule) : null
        if (ro) ro.observe(root)

        return () => {
            cancelAnimationFrame(raf)
            if (ro) ro.disconnect()
            marqueeStatesRef.current.forEach((s) => {
                if (s.svg && s.svg.parentNode) s.svg.parentNode.removeChild(s.svg)
            })
            marqueeStatesRef.current = []
        }
    }, [
        isStatic, N, radius, primarySpeed, scriptSpeed, resolved, wordCount, blend,
        // rebuild the SVG marquees when the type changes (they read the heading's
        // computed font at build time)
        customType, size1, size2,
        JSON.stringify(font1), JSON.stringify(font2),
    ])

    // ---- input: drag (a still tap navigates the centered section) ------
    const onPointerDown = useCallback(
        (e: React.PointerEvent) => {
            if (isStatic) return
            draggingRef.current = true
            movedRef.current = false
            startYRef.current = e.clientY
            startRawRef.current = rawRef.current
            lastInputRef.current = performance.now()
            modeRef.current = "scrub"
            ;(e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId)
        },
        [isStatic]
    )
    const onPointerMove = useCallback((e: React.PointerEvent) => {
        if (!draggingRef.current) return
        if (Math.abs(e.clientY - startYRef.current) > 5) movedRef.current = true
        rawRef.current = startRawRef.current - (e.clientY - startYRef.current)
        lastInputRef.current = performance.now()
        modeRef.current = "scrub"
    }, [])
    const onPointerUp = useCallback(() => {
        if (!draggingRef.current) return
        draggingRef.current = false
        lastInputRef.current = performance.now()
        if (movedRef.current) return // a drag, not a click
        const item = resolvedRef.current[centerIdxRef.current]
        if (!item) return
        const a = anchorsRef.current.get(item.src)
        if (a) {
            a.click() // lets Framer's router handle CMS links correctly
            return
        }
        if (item.href) {
            if (newTabRef.current) window.open(item.href, "_blank", "noopener")
            else window.location.href = item.href
        }
    }, [])

    // Navigate a section's link (shared by the pointer tap and the accessible
    // keyboard links). Uses the real CMS anchor so Framer routes it correctly.
    const navigateItem = useCallback((item: Resolved) => {
        const a = anchorsRef.current.get(item.src)
        if (a) {
            a.click()
            return
        }
        if (item.href) {
            if (newTabRef.current) window.open(item.href, "_blank", "noopener")
            else window.location.href = item.href
        }
    }, [])

    // Glide section `i` to the centre — used when its accessible link receives
    // keyboard focus, so tabbing genuinely walks the story into view.
    const centerSection = useCallback(
        (i: number) => {
            if (isStatic) return
            const root = rootRef.current
            if (!root) return
            const panelH = root.offsetHeight
            if (panelH <= 0 || N <= 0) return
            const S = N * panelH
            const base = i * panelH
            const cur = rawRef.current
            const target = base + Math.round((cur - base) / S) * S
            const now = performance.now()
            snapStartRef.current = offRef.current
            snapTargetRef.current = target
            snapT0Ref.current = now
            rawRef.current = target
            lastInputRef.current = now
            modeRef.current = "snap"
        },
        [isStatic, N]
    )

    // ---- input: wheel ---------------------------------------------------
    useEffect(() => {
        if (isStatic || !wheel) return
        const root = rootRef.current
        if (!root) return
        const onWheel = (e: WheelEvent) => {
            e.preventDefault()
            rawRef.current += e.deltaY
            lastInputRef.current = performance.now()
            modeRef.current = "scrub"
        }
        root.addEventListener("wheel", onWheel, { passive: false })
        return () => root.removeEventListener("wheel", onWheel)
    }, [isStatic, wheel])

    // ---- main rAF loop --------------------------------------------------
    useEffect(() => {
        if (isStatic) return
        let frame = 0
        let running = false
        const posByPanel: number[] = []

        const tick = () => {
            if (!running) return
            const now = performance.now()
            const dt = Math.min(0.05, (now - lastFrameRef.current) / 1000)
            lastFrameRef.current = now

            const root = rootRef.current
            const panelH = root ? root.offsetHeight : 0
            if (panelH > 0 && N > 0) {
                const S = N * panelH

                if (modeRef.current === "scrub") {
                    const k = 1 - Math.pow(0.9, dt * 60)
                    offRef.current += (rawRef.current - offRef.current) * k
                    // snap once input has been idle for 500ms; aim at the panel
                    // nearest to where we'll actually settle (raw), and start the
                    // glide from the live eased position for a seamless handoff
                    if (!draggingRef.current && now - lastInputRef.current > 500) {
                        const target = Math.round(rawRef.current / panelH) * panelH
                        snapStartRef.current = offRef.current
                        snapTargetRef.current = target
                        snapT0Ref.current = now
                        rawRef.current = target
                        modeRef.current = "snap"
                    }
                } else if (modeRef.current === "snap") {
                    // smooth eased glide over snapMs (ms), quart ease-out
                    const t = clampN((now - snapT0Ref.current) / snapMs, 0, 1)
                    if (t >= 1) {
                        offRef.current = snapTargetRef.current
                        modeRef.current = "idle"
                    } else {
                        offRef.current =
                            snapStartRef.current +
                            (snapTargetRef.current - snapStartRef.current) * easeOutQuart(t)
                    }
                } else {
                    offRef.current = rawRef.current
                }

                const off = offRef.current

                // scroll velocity (px/frame), low-pass smoothed -> motion blur
                const instVel = Math.abs(off - prevOffRef.current)
                prevOffRef.current = off
                velRef.current += (instVel - velRef.current) * 0.25
                const blurPx =
                    motionBlur > 0 ? Math.min(velRef.current * 0.25, motionBlur) : 0

                // sections: wrap + parallax + depth; track the centered one
                let bestIdx = 0
                let bestAbs = Infinity
                for (let i = 0; i < N; i++) {
                    const panel = panelRefs.current[i]
                    let pos = (((i * panelH - off) % S) + S) % S
                    if (pos > S - panelH) pos -= S
                    posByPanel[i] = pos
                    const ap = pos < 0 ? -pos : pos
                    if (ap < bestAbs) {
                        bestAbs = ap
                        bestIdx = i
                    }

                    if (panel) {
                        if (depth) {
                            const d = Math.min(Math.abs(pos) / panelH, 1)
                            const dscale = 1 - d * 0.08
                            panel.style.transform = `translate3d(0, ${pos}px, 0) scale(${dscale})`
                            panel.style.opacity = String(1 - d * 0.25)
                        } else {
                            panel.style.transform = `translate3d(0, ${pos}px, 0)`
                            panel.style.opacity = "1"
                        }
                    }

                    let r = pos / panelH
                    if (r > 1) r = 1
                    if (r < -1) r = -1

                    const media = mediaRefs.current[i]
                    if (media) {
                        media.style.transform = `translate3d(0, ${-parallax * r}%, 0)`
                    }

                    // ken burns slow zoom + velocity blur on the image itself
                    const img = imgRefs.current[i]
                    if (img) {
                        if (zoom) {
                            const ks = 1.05 + 0.05 * Math.sin(now * 0.0002 + i * 1.3)
                            img.style.transform = `scale(${ks.toFixed(4)})`
                        }
                        img.style.filter = blurPx > 0.05 ? `blur(${blurPx.toFixed(2)}px)` : "none"
                    }

                    // text rise: words drift vertically against the scroll
                    const textLayer = textRefs.current[i]
                    if (textLayer) {
                        const ty = textRise > 0 ? (textRise / 100) * pos * 0.5 : 0
                        textLayer.style.transform = `translate3d(0, ${ty.toFixed(2)}px, 0)`
                    }
                }
                centerIdxRef.current = bestIdx

                // marquees: continuous scroll + scale 1.5 -> 0.5 across viewport
                const states = marqueeStatesRef.current
                for (let i = 0; i < states.length; i++) {
                    const s = states[i]
                    const pos = posByPanel[s.panel] ?? 0
                    const scale = clampN(1 + 0.5 * (pos / panelH), 0.5, 1.5)
                    s.svg.style.transform = `scale(${scale})`
                    s.offsetX += s.speedPx * dt
                    const x = ((s.offsetX % s.loopLen) + s.loopLen) % s.loopLen
                    s.tp.setAttribute("startOffset", `${(-x).toFixed(3)}px`)
                }
            }
            frame = requestAnimationFrame(tick)
        }

        const start = () => {
            if (running) return
            running = true
            lastFrameRef.current = performance.now()
            frame = requestAnimationFrame(tick)
        }
        const stop = () => {
            running = false
            cancelAnimationFrame(frame)
        }
        // Only animate while the story is in the viewport, so multiple instances
        // don't burn CPU/GPU offscreen. Pauses when scrolled away, resumes on
        // return (dt is reset in start() so it never jumps).
        const root = rootRef.current
        if (!root || typeof IntersectionObserver === "undefined") {
            start()
            return () => stop()
        }
        const io = new IntersectionObserver(
            (entries) => {
                for (const e of entries) {
                    if (e.isIntersecting) start()
                    else stop()
                }
            },
            { threshold: 0 }
        )
        io.observe(root)
        return () => {
            io.disconnect()
            stop()
        }
    }, [isStatic, N, parallax, snapMs, textRise, motionBlur, zoom, depth])

    // ---- render ---------------------------------------------------------
    const rootH =
        typeof props.height === "number" && props.height > 0 ? props.height : undefined
    const renderItems = isStatic ? resolved.slice(0, 1) : resolved
    const showScript = wordCount === "two"

    const headingBase: React.CSSProperties = {
        textAlign: "center",
        whiteSpace: "nowrap",
        userSelect: "none",
        margin: 0,
        fontWeight: 400,
        lineHeight: 1,
    }

    const primaryType: React.CSSProperties = customType
        ? { ...(font1 || {}), fontSize: `${size1}vw` }
        : {
              fontFamily: PRIMARY_FONT,
              fontSize: PRIMARY_SIZE,
              textTransform: "uppercase",
              fontVariationSettings: "'wdth' 80",
          }
    const scriptType: React.CSSProperties = customType
        ? { ...(font2 || {}), fontSize: `${size2}vw` }
        : { fontFamily: SCRIPT_FONT, fontSize: SCRIPT_SIZE }

    return (
        <div
            ref={rootRef}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPointerCancel={onPointerUp}
            style={{
                position: "relative",
                width: "100%",
                height: rootH ?? `${sectionHeight}svh`,
                minHeight: `${sectionHeight}svh`,
                overflow: "hidden",
                background,
                touchAction: isStatic ? "auto" : "none",
                userSelect: "none",
                WebkitUserSelect: "none",
            }}
        >
            {renderItems.map((item, i) => {
                const initialPos = isStatic ? 0 : i === 0 ? 0 : 99999
                return (
                    <div
                        key={i}
                        ref={(el) => {
                            panelRefs.current[i] = el
                        }}
                        style={{
                            position: "absolute",
                            inset: 0,
                            transform: `translate3d(0, ${initialPos}px, 0)`,
                            willChange: "transform, opacity",
                            overflow: "clip",
                            display: "grid",
                            placeItems: "center",
                            cursor: item.href ? "pointer" : "inherit",
                        }}
                    >
                        {/* parallax image */}
                        <div
                            ref={(el) => {
                                mediaRefs.current[i] = el
                            }}
                            style={{
                                position: "absolute",
                                inset: 0,
                                zIndex: -1,
                                background: "#000",
                                willChange: "transform",
                                overflow: "hidden",
                            }}
                        >
                            <img
                                ref={(el) => {
                                    imgRefs.current[i] = el
                                }}
                                src={item.src}
                                alt={
                                    [item.primary, item.script]
                                        .filter(Boolean)
                                        .join(" ") || "Story section"
                                }
                                draggable={false}
                                style={{
                                    display: "block",
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                    willChange: "transform, filter",
                                }}
                            />
                        </div>

                        {/* curved marquees (text-rise layer). aria-hidden: this
                            is the decorative animated rendering of the words;
                            the accessible name lives on the section image alt
                            and the section link, so it isn't announced twice. */}
                        <div
                            ref={(el) => {
                                textRefs.current[i] = el
                            }}
                            aria-hidden="true"
                            style={{
                                position: "relative",
                                width: "100%",
                                willChange: "transform",
                            }}
                        >
                            {item.primary ? (
                                <div
                                    data-rtm-wrap=""
                                    data-panel={i}
                                    data-kind="primary"
                                    data-speed={primarySpeed}
                                    data-radius={radius}
                                    data-spacer="."
                                    data-spacer-color={item.primaryColor}
                                    style={{
                                        width: "100%",
                                        transform: "translateY(-60%)",
                                    }}
                                >
                                    <div
                                        data-rtm-text=""
                                        style={{
                                            ...headingBase,
                                            opacity: isStatic ? 1 : 0,
                                            color: item.primaryColor,
                                            ...primaryType,
                                        }}
                                    >
                                        {item.primary}
                                    </div>
                                </div>
                            ) : null}

                            {showScript && item.script ? (
                                <div
                                    data-rtm-wrap=""
                                    data-panel={i}
                                    data-kind="script"
                                    data-speed={scriptSpeed}
                                    data-radius={radius}
                                    data-spacer=" "
                                    data-spacer-color={item.scriptColor}
                                    style={{
                                        position: "absolute",
                                        inset: "10% 0 0 0",
                                        width: "100%",
                                        transform: "translateY(-60%)",
                                    }}
                                >
                                    <div
                                        data-rtm-text=""
                                        style={{
                                            ...headingBase,
                                            opacity: isStatic ? 1 : 0,
                                            color: item.scriptColor,
                                            ...scriptType,
                                        }}
                                    >
                                        {item.script}
                                    </div>
                                </div>
                            ) : null}
                        </div>
                    </div>
                )
            })}

            {/* Accessible link layer: a real, keyboard-focusable <a> per LINKED
                section. Mouse is handled by the root (drag vs tap), so these are
                pointerEvents:none — the keyboard/AT layer only. Focusing one
                glides its section to centre, so Tab walks the story; Enter/Space
                follows the link (routed through the real CMS anchor). */}
            {!isStatic &&
                resolved.map((item, i) => {
                    if (!item.href) return null
                    const words = [item.primary, item.script]
                        .filter(Boolean)
                        .join(" ")
                        .trim()
                    return (
                        <a
                            key={"lnk" + i}
                            href={item.href}
                            aria-label={
                                "Open " + (words || "section " + (i + 1))
                            }
                            onFocus={() => centerSection(i)}
                            onClick={(e) => {
                                e.preventDefault()
                                navigateItem(item)
                            }}
                            onKeyDown={(e) => {
                                if (e.key === " ") {
                                    e.preventDefault()
                                    ;(e.currentTarget as HTMLElement).click()
                                }
                            }}
                            style={{
                                position: "absolute",
                                inset: 0,
                                zIndex: 3,
                                pointerEvents: "none", // mouse handled by the root
                                textDecoration: "none",
                                color: "transparent",
                                outlineOffset: "-3px",
                            }}
                        />
                    )
                })}

            {/* hidden CMS probe (rendered on canvas too so the design previews CMS) */}
            {source === "cms" && (
                <div
                    ref={probeRef}
                    aria-hidden
                    style={{
                        position: "absolute",
                        left: -99999,
                        top: 0,
                        width: 1200,
                        height: 1,
                        opacity: 0,
                        pointerEvents: "none",
                        overflow: "hidden",
                    }}
                >
                    {collectionSlot}
                </div>
            )}
        </div>
    )
}

InfiniteStory.displayName = "Infinite Story"

